import hashlib
import hmac
import time
import os
import threading
from collections import defaultdict
from functools import wraps

# Rate limiting infrastructure
class RateLimiter:
    def __init__(self, max_attempts=5, window_seconds=60):
        self._attempts = defaultdict(list)
        self._lock = threading.Lock()
        self.max_attempts = max_attempts
        self.window_seconds = window_seconds

    def check(self, client_id):
        now = time.time()
        with self._lock:
            attempts = self._attempts[client_id]
            # Prune old attempts
            self._attempts[client_id] = [
                t for t in attempts if now - t < self.window_seconds
            ]
            if len(self._attempts[client_id]) >= self.max_attempts:
                return False
            self._attempts[client_id].append(now)
            return True


# Retry decorator for transient failures
def with_retry(max_retries=3, backoff_base=0.1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except TransientError as e:
                    last_exc = e
                    time.sleep(backoff_base * (2 ** attempt))
            raise last_exc
        return wrapper
    return decorator


class TransientError(Exception):
    pass


class AuthenticationError(Exception):
    pass


# Token verification engine
class TokenVerifier:
    """Verifies HMAC-based authentication tokens with rate limiting."""

    def __init__(self, secret_key, algorithm='sha256'):
        if isinstance(secret_key, str):
            secret_key = secret_key.encode('utf-8')
        self._secret = secret_key
        self._algorithm = algorithm
        self._rate_limiter = RateLimiter(max_attempts=10, window_seconds=30)
        self._nonce_cache = set()
        self._nonce_lock = threading.Lock()

    def _compute_mac(self, message, nonce, timestamp):
        """Compute HMAC over message components."""
        payload = self._serialize_payload(message, nonce, timestamp)
        return hmac.new(self._secret, payload, self._algorithm).digest()

    def _serialize_payload(self, message, nonce, timestamp):
        """Serialize components into a canonical byte string."""
        parts = []
        for component in (message, nonce, timestamp):
            if isinstance(component, memoryview):
                component = bytes(component)
            elif isinstance(component, (int, float)):
                component = str(component).encode('utf-8')
            elif isinstance(component, str):
                component = component.encode('utf-8')
            elif isinstance(component, bytearray):
                component = bytes(component)
            # bytes pass through unchanged
            parts.append(component)
        # Length-prefix each part to prevent ambiguity
        serialized = b''
        for part in parts:
            serialized += len(part).to_bytes(4, 'big') + part
        return serialized

    def _check_nonce(self, nonce):
        """Prevent replay attacks by tracking used nonces."""
        with self._nonce_lock:
            if nonce in self._nonce_cache:
                return False
            self._nonce_cache.add(nonce)
            # Limit cache size
            if len(self._nonce_cache) > 100000:
                self._nonce_cache.clear()
            return True

    @with_retry(max_retries=2, backoff_base=0.05)
    def verify_token(self, client_id, message, nonce, timestamp, provided_mac):
        """Verify an authentication token with rate limiting and replay protection."""
        if not self._rate_limiter.check(client_id):
            raise AuthenticationError("Rate limit exceeded")

        # Validate timestamp freshness (5 minute window)
        current_time = time.time()
        if abs(current_time - float(timestamp)) > 300:
            raise AuthenticationError("Token expired")

        # Check nonce for replay
        if not self._check_nonce(nonce):
            raise AuthenticationError("Nonce reuse detected")

        # Compute expected MAC
        expected_mac = self._compute_mac(message, nonce, timestamp)

        # Constant-time comparison
        if not hmac.compare_digest(expected_mac, provided_mac):
            raise AuthenticationError("Invalid token")

        return True

    def generate_token(self, message):
        """Generate a fresh authentication token."""
        nonce = os.urandom(16)
        timestamp = str(time.time())
        mac = self._compute_mac(message, nonce, timestamp)
        return {
            'nonce': nonce,
            'timestamp': timestamp,
            'mac': mac
        }


# Service layer
class SecureAPIGateway:
    def __init__(self, secret):
        self._verifier = TokenVerifier(secret)

    def authenticate_request(self, client_id, request_body, auth_header):
        """Authenticate an incoming API request."""
        try:
            nonce = auth_header['nonce']
            timestamp = auth_header['timestamp']
            mac = auth_header['mac']
        except (KeyError, TypeError):
            raise AuthenticationError("Malformed auth header")

        return self._verifier.verify_token(
            client_id, request_body, nonce, timestamp, mac
        )
